Lemma lit_chunked_bytes : forall m, mem_inv rsegs m -> bytes_at rsegs m A_CHUNKED (litb LIT_CHUNKED).
Proof.
  intros m MI. apply (ro_cells_bytes_at rsegs m A_CHUNKED [CB 7 (litb LIT_CHUNKED)]).
  apply (ro_cells_image rsegs m); [exact MI | vm_compute; reflexivity | unfold A_CHUNKED; lia | cbn; unfold A_CHUNKED; lia].
Qed.
Lemma lit_close_bytes : forall m, mem_inv rsegs m -> bytes_at rsegs m A_CLOSE (litb LIT_CLOSE).
Proof.
  intros m MI. apply (ro_cells_bytes_at rsegs m A_CLOSE [CB 5 (litb LIT_CLOSE)]).
  apply (ro_cells_image rsegs m); [exact MI | vm_compute; reflexivity | unfold A_CLOSE; lia | cbn; unfold A_CLOSE; lia].
Qed.
Lemma lit_keepalive_bytes : forall m, mem_inv rsegs m -> bytes_at rsegs m A_KEEPALIVE (litb LIT_KEEPALIVE).
Proof.
  intros m MI. apply (ro_cells_bytes_at rsegs m A_KEEPALIVE [CB 10 (litb LIT_KEEPALIVE)]).
  apply (ro_cells_image rsegs m); [exact MI | vm_compute; reflexivity | unfold A_KEEPALIVE; lia | cbn; unfold A_KEEPALIVE; lia].
Qed.
Lemma lit_upgrade_bytes : forall m, mem_inv rsegs m -> bytes_at rsegs m A_UPGRADE (litb LIT_UPGRADE).
Proof.
  intros m MI. apply (ro_cells_bytes_at rsegs m A_UPGRADE [CB 7 (litb LIT_UPGRADE)]).
  apply (ro_cells_image rsegs m); [exact MI | vm_compute; reflexivity | unfold A_UPGRADE; lia | cbn; unfold A_UPGRADE; lia].
Qed.

