(* [comment removed for export] *)
Lemma te_ieq_fast : forall (r : nat) (i : Z) rax spx gp tp t0 t1 t2 s0 s1 a0 a6 a7 s2 s3 s4 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (vp vq : Z) (vbs : list byte),
  bytes_at rsegs m1 vp vbs -> bytes_at rsegs m1 A_CHUNKED (litb LIT_CHUNKED) -> mem_inv rsegs m1 ->
  vp <= vq -> vq + 7 <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) < 2^64 ->
  0 <= i -> i + Z.of_nat r = 7 ->
  evt rsegs (fun ms' => exists a0' a1' a2' a3' a4' a5' a6' a7' pc',
      ms' = MS (te_regs rax spx gp tp t0 t1 t2 s0 s1 a0' a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 (wz A_CHUNKED) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 pc') fc None m1 (seg_rom rsegs)
      /\ (pc' = 0x3b938 \/ pc' = 0x3b874))
    (MS (te_regs rax spx gp tp t0 t1 t2 s0 s1 a0 (wz (- i)) (wz vq) (wz (Z.of_nat r)) (wz (A_CHUNKED + i)) (wz (vq + i)) a6 a7 s2 s3 s4 (wz A_CHUNKED) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
