    (vp : Z) (vbs : list byte) (La : Z) (j0 jc jm ji jv : list byte) (vq vl iq fq : Z) (g : bool) : Prop :=
  rw_cells rsegs m1 (bv_unsigned sp + -288) [CB 8 j0]
