Definition te_inv (vp La vq vl iq fq B : Z) : Prop :=
  (vq = 0 /\ vl = 0 /\ iq = La /\ fq = La /\ 0 < B)
  \/ (vp <= vq /\ 0 <= vl /\ vq + vl <= iq /\ iq <= La /\ vp <= fq /\ fq < iq /\ 2 * (La - fq) + 1 < B).

