Lemma te_all : forall n, TE_AT (Z.of_nat n).
Proof.
  induction n as [|n IH].
  - intros vq vl iq fq. intros until g. intros CTX PURE F1 INV. exfalso.
    destruct INV as [(_ & _ & _ & _ & HB)|(_ & _ & N3 & N4 & _ & N6 & HB)]; cbn [Z.of_nat] in HB; lia.
  - rewrite Nat2Z.inj_succ. replace (Z.succ (Z.of_nat n)) with (Z.of_nat n + 1) by lia. apply te_step. exact IH.
Qed.

